u0438\u0437\u043e\u043d\u0442\u043e\u0432: \u0443 \u0441\u0438\u043b\u044c\u043d\u043e\u043f\u0435\u0440\u0438\u043e\u0434\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0440\u044f\u0434\u043e\u0432 (\u0441\u0443\u0442\u043e\u0447\u043d\u0430\u044f/\u043d\u0435\u0434\u0435\u043b\u044c\u043d\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430) \u043c\u043e\u0434\u0435\u043b\u044c \u0442\u0440\u0430\u0442\u0438\u0442 \u043e\u0431\u0443\u0447\u0430\u044e\u0449\u0443\u044e \u0451\u043c\u043a\u043e\u0441\u0442\u044c \u043d\u0430 \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u043f\u0435\u0440\u0438\u043e\u0434\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043d/\u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0443\u0435\u043c. \u0418\u0434\u0435\u044f: **\u0432\u044b\u0434\u0435\u043b\u0438\u0442\u044c \u043f\u0435\u0440\u0438\u043e\u0434\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0443 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0439 \u043e\u0431\u0443\u0447\u0430\u0435\u043c\u043e\u0439 \u00ab\u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0432\u0435\u0442\u0432\u044c\u044e\u00bb, \u0430 \u043d\u0430 \u0434\u043e\u043b\u044e \u0431\u0430\u0437\u043e\u0432\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438 (backbone) \u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0435\u043f\u0435\u0440\u0438\u043e\u0434\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043e\u0441\u0442\u0430\u0442\u043e\u043a**; \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u043f\u0440\u043e\u0433\u043d\u043e\u0437 = \u043f\u0440\u043e\u0433\u043d\u043e\u0437 \u043e\u0441\u0442\u0430\u0442\u043a\u0430 + \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0435\u043d\u043d\u0430\u044f \u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0430.\n\n\u042d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442 \u0442\u0440\u0438 \u0444\u0430\u043b\u044c\u0441\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u044b\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f:\n- **R1 (\u0440\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u043c\u043e\u0441\u0442\u044c/\u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c):** residual CycleNet \u043e\u0431\u0443\u0447\u0430\u0435\u0442\u0441\u044f \u0438 \u043d\u0430 \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0435 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u0439 \u043f\u0435\u0440\u0438\u043e\u0434 (\u0432\u043b\u043e\u0436\u0435\u043d\u0438\u0435 W \u0431\u043b\u0438\u0437\u043a\u043e \u043a \u00ab\u0438\u0441\u0442\u0438\u043d\u043d\u043e\u0439\u00bb \u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0435).\n- **R2 (\u0432\u043a\u043b\u0430\u0434 \u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0432\u0435\u0442\u0432\u0438):** residual CycleNet \u0441 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u044b\u043c `r_cycle` \u043d\u0435 \u0445\u0443\u0436\u0435 (\u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e \u2014 \u043b\u0443\u0447\u0448\u0435) \u0442\u043e\u0433\u043e \u0436\u0435 backbone \u0431\u0435\u0437 \u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0432\u0435\u0442\u0432\u0438 \u043d\u0430 \u22653 \u0438\u0437 4 \u043f\u0435\u0440\u0438\u043e\u0434\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432.\n- **R3 (\u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0441\u0442\u044c):** \u043d\u0430 \u043d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u043e\u043c \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435 (\u0440\u044f\u0434 \u0431\u0435\u0437 \u0432\u044b\u0440\u0430\u0436\u0435\u043d\u043d\u043e\u0439 \u043f\u0435\u0440\u0438\u043e\u0434\u0438\u0447\u043d\u043e\u0441\u0442\u0438) \u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0432\u0435\u0442\u0432\u044c \u043d\u0435 \u0434\u0430\u0451\u0442 \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0433\u043e \u0443\u0445\u0443\u0434\u0448\u0435\u043d\u0438\u044f.\n\n\u041a\u0430\u0436\u0434\u044b\u0439 \u0442\u0435\u0437\u0438\u0441 \u2014 \u0441 \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438 \u043c\u0435\u0442\u0440\u0438\u043a\u0430\u043c\u0438 \u0438 \u043f\u043e\u0440\u043e\u0433\u0430\u043c\u0438 (\u00a76\u20138), \u0447\u0442\u043e\u0431\u044b \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0431\u044b\u043b \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0438\u0440\u0443\u0435\u043c \u0438 \u043f\u0440\u0438 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u043c \u0438\u0441\u0445\u043e\u0434\u0435.\n\n---\n\n## 2. \u0421\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u043c\u043e\u0434\u0435\u043b\u0438\n\n### 2.1 \u041e\u0431\u043e\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u0438 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\n- \u0423\u043d\u0438\u0432\u0430\u0440\u0438\u0430\u0442\u043d\u044b\u0439 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b: \u043a\u0430\u0436\u0434\u0430\u044f \u0441\u0435\u0440\u0438\u044f \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0443\u0435\u0442\u0441\u044f \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e (z-score, \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0438 \u0442\u043e\u043b\u044c\u043a\u043e \u0438\u0437 train); \u043f\u0440\u043e\u0433\u043d\u043e\u0437 \u0432\u0435\u0434\u0451\u0442\u0441\u044f \u043f\u043e \u0441\u0435\u0440\u0438\u0438 \u0432 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438. \u041c\u0443\u043b\u044c\u0442\u0438\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u043d\u0430\u044f \u0432\u0435\u0440\u0441\u0438\u044f \u2014 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0435 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435 (\u043d\u0435 \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u0431\u0430\u0437\u043e\u0432\u0443\u044e \u043c\u0430\u0442\u0440\u0438\u0446\u0443 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u043e\u0432).\n- \u0412\u0445\u043e\u0434\u043d\u043e\u0435 \u043e\u043a\u043d\u043e: `X = [x_1, \u2026, x_L] \u2208 R^L` (`L = seq_len`), \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442: `[x_{L+1}, \u2026, x_{L+H}]` (`H = pred_len`).\n- \u0414\u043b\u0438\u043d\u0430 \u043f\u0435\u0440\u0438\u043e\u0434\u0430: `r = r_cycle`; \u0447\u0438\u0441\u043b\u043e \u0446\u0438\u043a\u043b\u043e\u0432 \u0432 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0435: `n = n_cycles`.\n\n### 2.2 \u0426\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0432\u0435\u0442\u0432\u044c\n- \u041e\u0431\u0443\u0447\u0430\u0435\u043c\u044b\u0439 \u00ab\u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0441\u043b\u043e\u0432\u0430\u0440\u044c\u00bb: `W \u2208 R^{n \u00d7 r}`. \u0421\u0442\u0440\u043e\u043a\u0430 `i` \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u0446\u0438\u043a\u043b \u043f\u0440\u043e\u0448\u043b\u043e\u0433\u043e, \u0441\u0442\u043e\u043b\u0431\u0435\u0446 `j` \u2014 \u0444\u0430\u0437\u0430 (\u043f\u043e\u0437\u0438\u0446\u0438\u044f \u0432\u043d\u0443\u0442\u0440\u0438 \u043f\u0435\u0440\u0438\u043e\u0434\u0430).\n- \u0414\u043b\u044f \u043f\u043e\u0437\u0438\u0446\u0438\u0438 `t` \u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0430 \u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u0438\u0437 \u0441\u043b\u043e\u0432\u0430\u0440\u044f: `c_t = W[i_t, j_t]`, \u0433\u0434\u0435 `j_t = (t\u22121) mod r` (\u0444\u0430\u0437\u0430), `i_t` \u2014 \u0438\u043d\u0434\u0435\u043a\u0441 \u0441\u0442\u0440\u043e\u043a\u0438 \u0446\u0438\u043a\u043b\u0430 (\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f \u043f\u043e\u0437\u0438\u0446\u0438\u0435\u0439 `t` \u0432\u043d\u0443\u0442\u0440\u0438 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0430; \u043f\u0440\u0438 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0435\u043d\u0438\u0438 \u0432\u043f\u0435\u0440\u0451\u0434 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u044f\u044f(\u0438\u0435) \u0441\u0442\u0440\u043e\u043a\u0430(\u0438) \u0441\u043b\u043e\u0432\u0430\u0440\u044f \u2014 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u00ab\u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0435\u043d\u0438\u044f \u043f\u0435\u0440\u0438\u043e\u0434\u0430\u00bb, \u043a\u0430\u043a \u0432 \u043e\u0440\u0438\u0433\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438).\n- \u041f\u0440\u043e\u0434\u043e\u043b\u0436\u0435\u043d\u0438\u0435 \u0446\u0438\u043a\u043b\u0430 \u043d\u0430 \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442: `c_{L+h}` \u0434\u043b\u044f `h = 1..H` \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442\u0441\u044f \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0435\u043d\u0438\u0435\u043c \u0444\u0430\u0437 \u0441\u043b\u043e\u0432\u0430\u0440\u044f \u0432\u043f\u0435\u0440\u0451\u0434 \u043f\u043e `j`.\n\n### 2.3 Residual-\u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430\n1. \u0412\u044b\u0434\u0435\u043b\u0438\u0442\u044c \u043e\u0441\u0442\u0430\u0442\u043e\u043a: `z_t = x_t \u2212 c_t` \u0434\u043b\u044f \u0432\u0441\u0435\u0445 `t = 1..L` (\u0438\u0437 \u0432\u0445\u043e\u0434\u0430 \u0432\u044b\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043f\u0435\u0440\u0438\u043e\u0434\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0430).\n2. Backbone \u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u0443\u044e \u0447\u0430\u0441\u0442\u044c: `\\hat z_{L+1:L+H} = f(z_{1:L})`.\n3. \u0424\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u043f\u0440\u043e\u0433\u043d\u043e\u0437: `\\hat x_{L+h} = \\hat z_{L+h} + c_{L+h}` \u2014 \u043e\u0441\u0442\u0430\u0442\u043e\u043a \u043f\u043b\u044e\u0441 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0435\u043d\u043d\u044b\u0439 \u0446\u0438\u043a\u043b.\n\n### 2.4 Backbone `f`\n- **Linear (\u0431\u0430\u0437\u043e\u0432\u044b\u0439):** `\\hat z = Linear(Flatten(z_{1:L}))`, \u043f\u0440\u043e\u0435\u043a\u0446\u0438\u044f \u0447\u0435\u0440\u0435\u0437 \u0441\u043a\u0440\u044b\u0442\u0443\u044e \u0440\u0430\u0437\u043c\u0435\u0440\u043d\u043e\u0441\u0442\u044c `d_model`: `f(z) = W_2 \u00b7 (W_1 \u00b7 Flatten(z))`, `W_1: L\u2192d_model`, `W_2: d_model\u2192H`, \u0437\u0430\u0442\u0435\u043c reshape \u0432 `[H]`.\n- **DLinear/NLinear (\u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0435 \u0432\u0430\u0440\u0438\u0430\u043d\u0442\u044b):** DLinear = \u0434\u0435\u043a\u043e\u043c\u043f\u043e\u0437\u0438\u0446\u0438\u044f \u0442\u0440\u0435\u043d\u0434/\u043e\u0441\u0442\u0430\u0442\u043e\u043a (\u0441\u043a\u043e\u043b\u044c\u0437\u044f\u0449\u0435\u0435 \u0441\u0440\u0435\u0434\u043d\u0435\u0435) + \u0434\u0432\u0435 \u043b\u0438\u043d\u0435\u0439\u043d\u044b\u0435 \u043a\u0430\u0440\u0442\u044b; NLinear = \u0432\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0433\u043e \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f, \u043b\u0438\u043d\u0435\u0439\u043d\u0430\u044f \u043a\u0430\u0440\u0442\u0430, \u0432\u043e\u0437\u0432\u0440\u0430\u0442 \u0441\u0434\u0432\u0438\u0433\u0430. \u0412\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u0441\u044f \u043a\u0430\u043a \u0432\u0430\u0440\u0438\u0430\u043d\u0442\u044b backbone \u0432 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u0443\u044e \u0430\u0431\u043b\u044f\u0446\u0438\u044e A7.\n\n### 2.5 Vanilla (\u043d\u0435-residual) \u0432\u0430\u0440\u0438\u0430\u043d\u0442 \u2014 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u0430\u044f \u0430\u0431\u043b\u044f\u0446\u0438\u044f A6\n\u0427\u0442\u043e\u0431\u044b \u043e\u0442\u0434\u0435\u043b\u0438\u0442\u044c \u0432\u043a\u043b\u0430\u0434 \u00ab\u0430\u0434\u0434\u0438\u0442\u0438\u0432\u043d\u043e\u0439 \u043f\u0435\u0440\u0438\u043e\u0434\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0432\u0435\u0442\u0432\u0438\u00bb \u043e\u0442 \u00ab\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u0439 \u0434\u0435\u043a\u043e\u043c\u043f\u043e\u0437\u0438\u0446\u0438\u0438\u00bb, \u0432\u0430\u0440\u0438\u0430\u043d\u0442: `\\hat x = f(x_{1:L}) + c_{L+1:L+H}` \u2014 \u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0430 **\u043f\u0440\u0438\u0431\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f** \u043a \u0432\u044b\u0445\u043e\u0434\u0443 backbone, \u043e\u0431\u0443\u0447\u0435\u043d\u043d\u043e\u0433\u043e \u043d\u0430 \u0441\u044b\u0440\u043e\u043c \u0440\u044f\u0434\u0435, \u0431\u0435\u0437 \u0432\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u044f \u0438\u0437 \u0432\u0445\u043e\u0434\u0430. \u0421\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 residual vs vanilla \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u043a\u0430\u043a\u043e\u0439 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u0434\u0430\u0451\u0442 \u0432\u044b\u0438\u0433\u0440\u044b\u0448.\n\n### 2.6 \u0424\u0443\u043d\u043a\u0446\u0438\u044f \u043f\u043e\u0442\u0435\u0440\u044c\n`L = (1/(H\u00b7|T|)) \u03a3_{t\u2208T} \u03a3_{h=1..H} (x_{t+h} \u2212 \\hat x_{t+h})\u00b2` \u2014 MSE \u043f\u043e \u0432\u0441\u0435\u043c \u0432\u0430\u043b\u0438\u0434\u043d\u044b\u043c \u043e\u043a\u043d\u0430\u043c `T` (per-point \u0430\u0433\u0440\u0435\u0433\u0430\u0446\u0438\u044f). \u041e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0440\u0435\u0436\u0438\u043c \u2014 MAE.\n\n---\n\n## 3. \u0414\u0430\u0442\u0430\u0441\u0435\u0442\u044b \u0438 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u0434\u0430\u043d\u043d\u044b\u0445\n\n### 3.1 \u0421\u0438\u043d\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 sanity-check (\u043f\u0435\u0440\u0432\u044b\u0439, \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0448\u0430\u0433)\n- \u041a\u043e\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f: `x_t = A\u2081\u00b7sin(2\u03c0 t/r_true + \u03c6) + A\u2082\u00b7sin(2\u03c0 t/p\u2082) + \u03b2\u00b7t + \u03b5_t`, \u0433\u0434\u0435 `r_true` \u2014 \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u0443\u044e\u0449\u0438\u0439 \u043f\u0435\u0440\u0438\u043e\u0434 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, 24), `p\u2082` \u2014 \u0432\u0442\u043e\u0440\u0430\u044f \u0433\u0430\u0440\u043c\u043e\u043d\u0438\u043a\u0430 (168), `\u03b2` \u2014 \u0442\u0440\u0435\u043d\u0434, `\u03b5 ~ N(0, \u03c3\u00b2)`. \u0413\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0441 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u0441\u0438\u0434\u043e\u043c, \u043e\u043a\u043d\u0430 \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u043f\u043e \u0444\u0430\u0437\u0435 `\u03c6` \u0442\u0430\u043a, \u0447\u0442\u043e\u0431\u044b \u0441\u043b\u043e\u0432\u0430\u0440\u044c W \u0431\u044b\u043b \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u043c \u0441 \u0438\u0441\u0442\u0438\u043d\u043e\u0439.\n- \u041d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435: (\u0430) \u0434\u0435\u0448\u0451\u0432\u0430\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0441\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u0438 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0441\u0442\u0438 residual-\u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438; (\u0431) \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 R1 \u2014 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u043e\u0439 W-\u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u044b \u0441 \u0438\u0441\u0442\u0438\u043d\u043d\u043e\u0439 \u0441\u0438\u043d\u0443\u0441\u043e\u0438\u0434\u043e\u0439 (\u043f\u043e \u043d\u043e\u0440\u043c\u0435 \u043f\u043e\u0441\u043b\u0435 \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u044f \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0430/\u0441\u0434\u0432\u0438\u0433\u0430); (\u0432) \u0438\u0437\u043e\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0442\u0435\u0441\u0442 \u0431\u0435\u0437 \u043b\u044e\u0431\u044b\u0445 \u0443\u0442\u0435\u0447\u0435\u043a.\n\n### 3.2 \u0420\u0435\u0430\u043b\u044c\u043d\u044b\u0435 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u044b (\u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u0430\u044f \u0433\u0440\u0443\u043f\u043f\u0430)\n| \u0414\u0430\u0442\u0430\u0441\u0435\u0442 | \u0427\u0430\u0441\u0442\u043e\u0442\u0430 | \u041f\u0440\u0435\u0434\u043f\u043e\u043b\u0430\u0433\u0430\u0435\u043c\u044b\u0439 \u043f\u0435\u0440\u0438\u043e\u0434 `r_cycle` | \u041f\u0440\u0438\u043c\u0435\u0447\u0430\u043d\u0438\u0435 |\n|---|---|---|---|\n| ETTh1 | 1 \u0447\u0430\u0441 | 24 (\u0441\u0443\u0442\u043a\u0438), \u043d\u0435\u0434\u0435\u043b\u044f 168 | ~17 400 \u0442\u043e\u0447\u0435\u043a |\n| ETTm1 | 15 \u043c\u0438\u043d | 96 (\u0441\u0443\u0442\u043a\u0438) | ~69 600 \u0442\u043e\u0447\u0435\u043a |\n| Electricity (ECL) | 1 \u0447\u0430\u0441 | 168 (\u043d\u0435\u0434\u0435\u043b\u044f), \u0441\u0443\u0442\u043a\u0438 24 | ~26 300 \u0442\u043e\u0447\u0435\u043a |\n| Solar-Energy | 10 \u043c\u0438\u043d | 144 (\u0441\u0443\u0442\u043a\u0438) | ~52 500 \u0442\u043e\u0447\u0435\u043a |\n\n\u041f\u0435\u0440\u0438\u043e\u0434 \u043d\u0435 \u043f\u043e\u0441\u0442\u0443\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432\u0441\u043b\u0435\u043f\u0443\u044e: **\u043f\u0435\u0440\u0435\u0434 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u0435\u043c \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u044d\u043c\u043f\u0438\u0440\u0438\u0447\u0435\u0441\u043a\u0438** (\u0430\u0432\u0442\u043e\u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u044f + FFT-\u0441\u043f\u0435\u043a\u0442\u0440 \u043f\u043e train-\u0441\u0435\u0433\u043c\u0435\u043d\u0442\u0443 \u043a\u0430\u0436\u0434\u043e\u0439 \u0441\u0435\u0440\u0438\u0438) \u0438 \u0441\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u0441 \u0434\u043e\u043c\u0435\u043d\u043d\u044b\u043c\u0438 \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u044f\u043c\u0438; \u0438\u0442\u043e\u0433\u043e\u0432\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 `r_cycle` \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432 \u043a\u043e\u043d\u0444\u0438\u0433\u0435 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430. \u0421\u043c. \u0442\u0430\u043a\u0436\u0435 \u0430\u0431\u043b\u044f\u0446\u0438\u044e A5 (\u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043a \u043e\u0448\u0438\u0431\u043a\u0435 \u043f\u0435\u0440\u0438\u043e\u0434\u0430).\n\n### 3.3 \u041d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\n- **Exchange rate** (~7 600 \u0442\u043e\u0447\u0435\u043a, \u043d\u0435\u0434\u0435\u043b\u044c\u043d\u0430\u044f/\u0435\u0436\u0435\u0434\u043d\u0435\u0432\u043d\u0430\u044f \u0447\u0430\u0441\u0442\u043e\u0442\u0430, \u0441\u043b\u0430\u0431\u0430\u044f \u043f\u0435\u0440\u0438\u043e\u0434\u0438\u0447\u043d\u043e\u0441\u0442\u044c): \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 R3 \u2014 \u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0432\u0435\u0442\u0432\u044c \u043d\u0435 \u0434\u043e\u043b\u0436\u043d\u0430 \u0437\u043d\u0430\u0447\u0438\u043c\u043e \u0443\u0445\u0443\u0434\u0448\u0430\u0442\u044c \u043f\u0440\u043e\u0433\u043d\u043e\u0437 \u043f\u0440\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0438 \u0432\u044b\u0440\u0430\u0436\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u0435\u0440\u0438\u043e\u0434\u0430 (\u0434\u043b\u044f \u043d\u0435\u0433\u043e `r_cycle` \u0441\u0442\u0430\u0432\u0438\u0442\u0441\u044f, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0432 24/168 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u2014 \u0441\u0430\u043c\u043e \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u043d\u0435\u043a\u0440\u0438\u0442\u0438\u0447\u043d\u043e).\n\n### 3.4 \u0421\u043f\u043b\u0438\u0442\u044b \u0438 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f (\u0431\u0435\u0437 \u0443\u0442\u0435\u0447\u0435\u043a)\n- \u0425\u0440\u043e\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0440\u0430\u0437\u0431\u0438\u0435\u043d\u0438\u0435 **70% train / 10% val / 20% test** (\u043f\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438, \u0411\u0415\u0417 \u043f\u0435\u0440\u0435\u043c\u0435\u0448\u0438\u0432\u0430\u043d\u0438\u044f \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u043e\u043a\u043e\u043d).\n- \u041d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f: per-series z-score; \u0441\u0440\u0435\u0434\u043d\u0435\u0435/\u0441\u0442. \u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0435 \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f **\u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e train** \u0438 \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u044e\u0442\u0441\u044f \u043a val/test. \u0414\u043b\u044f \u043c\u0435\u0442\u0440\u0438\u043a \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u043e\u0431\u0440\u0430\u0442\u043d\u043e\u0435 \u043f\u0440\u0435\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u0435.\n- \u041e\u0446\u0435\u043d\u043a\u0430: \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0439 LTSF-\u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u2014 \u0441\u043a\u043e\u043b\u044c\u0437\u044f\u0449\u0435\u0435 \u043e\u043a\u043d\u043e (\u0448\u0430\u0433 1) \u043f\u043e \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u043e\u043c\u0443 \u0442\u0435\u0441\u0442\u043e\u0432\u043e\u043c\u0443 \u0441\u0435\u0433\u043c\u0435\u043d\u0442\u0443; \u0430\u0433\u0440\u0435\u0433\u0430\u0446\u0438\u044f \u043e\u0448\u0438\u0431\u043e\u043a \u043f\u043e \u0432\u0441\u0435\u043c \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u043c \u043e\u043a\u043d\u0430\u043c **per-point**.\n- Val \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u0440\u0430\u043d\u043d\u0435\u0439 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438/\u0432\u044b\u0431\u043e\u0440\u0430 \u0447\u0435\u043a\u043f\u043e\u0439\u043d\u0442\u0430; \u043d\u0430 \u0442\u0435\u0441\u0442 \u043d\u0435 \u0441\u043c\u043e\u0442\u0440\u0438\u043c \u0434\u043e \u0444\u0438\u043a\u0441\u0430\u0446\u0438\u0438 \u0432\u0441\u0435\u0445 \u043a\u043e\u043d\u0444\u0438\u0433\u043e\u0432.\n\n---\n\n## 4. \u0413\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b: \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u0438 \u043e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435\n\n| \u041f\u0430\u0440\u0430\u043c\u0435\u0442\u0440 | \u0417\u043d\u0430\u0447\u0435\u043d\u0438\u0435 (\u0431\u0430\u0437\u043e\u0432\u043e) | \u0421\u0435\u0442\u043a\u0430/\u0432\u0430\u0440\u044c\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 | \u041e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435 |\n|---|---|---|---|\n| `seq_len` L | 336 | \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e | \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442 LTSF-\u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0430; \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0434\u043b\u044f \u0441\u0443\u0442\u043e\u0447\u043d\u043e\u0439/\u043d\u0435\u0434\u0435\u043b\u044c\u043d\u043e\u0439 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b |\n| `pred_len` H | {96, 168, 336, 720} (\u043f\u043e ETT/ECL); \u0434\u043b\u044f Solar/Exchange \u2014 \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e \u043f\u043e \u0434\u043b\u0438\u043d\u0435 \u0434\u0430\u043d\u043d\u044b\u0445 | \u043f\u043e-\u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442\u043d\u0430\u044f \u043e\u0446\u0435\u043d\u043a\u0430 | \u043f\u043e\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u0441\u0440\u0435\u0434\u043d\u0438\u0435 \u0438 \u0434\u043b\u0438\u043d\u043d\u044b\u0435 \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442\u044b; \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u0438\u043c\u043e \u0441 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u043e\u0439 |\n| `r_cycle` | 24/96/168/144 \u043f\u043e \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0443 (\u0441\u043c. \u00a73.2) | A5: 24\u00b11, 25, FFT-\u043e\u0446\u0435\u043d\u043a\u0430 | \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0441\u0442\u044c \u043f\u0435\u0440\u0438\u043e\u0434\u0430 \u2014 \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0444\u0430\u043a\u0442\u043e\u0440 \u043c\u043e\u0434\u0435\u043b\u0438 |\n| `n_cycles` | 3 | A4: {1, 2, 3, 5} | \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0446\u0438\u043a\u043b\u043e\u0432 \u043f\u0440\u043e\u0448\u043b\u043e\u0433\u043e \u043a\u043e\u0434\u0438\u0440\u0443\u0435\u0442 \u0441\u043b\u043e\u0432\u0430\u0440\u044c; \u043a\u043e\u043c\u043f\u0440\u043e\u043c\u0438\u0441\u0441 \u0451\u043c\u043a\u043e\u0441\u0442\u044c/\u043e\u0431\u043e\u0431\u0449\u0435\u043d\u0438\u0435 |\n| backbone | Linear | A7: DLinear, NLinear | Linear \u2014 \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0447\u0435\u0441\u0442\u043d\u044b\u0439 \u0431\u0430\u0437\u043e\u0432\u044b\u0439 backbone |\n| `d_model` | 256 | \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e (CPU-\u0431\u044e\u0434\u0436\u0435\u0442) | \u0440\u0430\u0437\u043c\u0435\u0440 \u0441\u043a\u0440\u044b\u0442\u043e\u0439 \u043f\u0440\u043e\u0435\u043a\u0446\u0438\u0438 |\n| `d_ff` / \u0441\u043b\u043e\u0439 | \u2014 (\u043d\u0435\u0442 FFN) | \u043e\u0434\u043d\u043e\u0441\u043b\u043e\u0439\u043d\u0430\u044f \u043f\u0440\u043e\u0435\u043a\u0446\u0438\u044f | \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u0438\u0437\u043c, \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0431\u044e\u0434\u0436\u0435\u0442\u0430 |\n| \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0442\u043e\u0440 | Adam | \u2014 | \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442 \u0434\u043b\u044f \u0442\u0430\u043a\u0438\u0445 \u043c\u043e\u0434\u0435\u043b\u0435\u0439 |\n| `lr` | 0.001\u20130.005 | ReduceLROnPlateau (factor 0.5, patience 2) \u0438\u043b\u0438 cosine | \u0438\u0437 reference-\u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0439 CycleNet |\n| `batch_size` | 128 (64 \u043f\u0440\u0438 \u0431\u043e\u043b\u044c\u0448\u0438\u0445 H) | {64, 128, 256} | \u043a\u043e\u043c\u043f\u0440\u043e\u043c\u0438\u0441\u0441 \u0441\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c/\u043f\u0430\u043c\u044f\u0442\u044c |\n| `max_epochs` | 50\u2013100 | \u2014 | \u043f\u043e\u0442\u043e\u043b\u043e\u043a \u0434\u043b\u044f \u0440\u0430\u043d\u043d\u0435\u0439 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438 |\n| `patience` (early stop) | 5\u201310 \u043d\u0430 val MSE | \u2014 | \u0437\u0430\u0449\u0438\u0442\u0430 \u043e\u0442 \u043f\u0435\u0440\u0435\u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f |\n| \u0441\u0438\u0434\u044b | 5 (0..4) | \u2014 | mean\u00b1std \u0434\u043b\u044f \u043d\u0430\u0434\u0451\u0436\u043d\u043e\u0441\u0442\u0438 \u0432\u044b\u0432\u043e\u0434\u043e\u0432 |\n| \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f | per-series z-score (train-stats) | \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e | \u0435\u0434\u0438\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u0438\u0435 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u043c\u043e\u0434\u0435\u043b\u0435\u0439 |\n\n\u0412\u0441\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u00ab\u0431\u0430\u0437\u043e\u0432\u043e\u00bb \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0432 JSON/YAML-\u043a\u043e\u043d\u0444\u0438\u0433\u0435 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430; \u0441\u0435\u0442\u043a\u0438 \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u044e\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0432\u043d\u0443\u0442\u0440\u0438 \u0430\u0431\u043b\u044f\u0446\u0438\u0439 (A4, A5, A7), \u0430 \u043d\u0435 \u043a\u0430\u043a \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u044b\u0439 \u0442\u044e\u043d\u0438\u043d\u0433 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438.\n\n---\n\n## 5. \u041c\u0430\u0442\u0440\u0438\u0446\u0430 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u043e\u0432 \u0438 \u0430\u0431\u043b\u044f\u0446\u0438\u0439\n\n\u041e\u0431\u043e\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435: RC-Lin = residual CycleNet (Linear backbone); BO-Lin = backbone-only Linear (\u0431\u0435\u0437 \u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0432\u0435\u0442\u0432\u0438); SN = season-naive; Lin = \u0447\u0438\u0441\u0442\u0430\u044f Linear; VC = vanilla (\u043d\u0435-residual) CycleNet.\n\n| ID | \u041c\u043e\u0434\u0435\u043b\u044c | \u0414\u0430\u0442\u0430\u0441\u0435\u0442\u044b | \u041d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 / \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u044b\u0439 \u0442\u0435\u0437\u0438\u0441 |\n|---|---|---|---|\n| E1 | RC-Lin (\u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u044b\u0439 `r`) | \u0421\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0430 | R1: \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u043f\u0435\u0440\u0438\u043e\u0434\u0430, \u0441\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0438 |\n| E2\u2013E5 | RC-Lin | ETTh1, ETTm1, ECL, Solar | \u041e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b, R2 |\n| E6 | RC-Lin | Exchange | \u041d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c, R3 |\n| A1 | BO-Lin (\u0442\u043e\u0442 \u0436\u0435 backbone, \u0431\u0435\u0437 \u0446\u0438\u043a\u043b\u0430), \u043e\u0431\u0443\u0447\u0435\u043d\u0430 \u043d\u0430 \u0441\u044b\u0440\u043e\u043c \u0440\u044f\u0434\u0435 | \u0432\u0441\u0435 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u044b | \u041a\u043b\u044e\u0447\u0435\u0432\u0430\u044f \u0430\u0431\u043b\u044f\u0446\u0438\u044f: \u0438\u0437\u043e\u043b\u0438\u0440\u0443\u0435\u0442 \u0432\u043a\u043b\u0430\u0434 \u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0432\u0435\u0442\u0432\u0438 (\u0442\u043e\u0442 \u0436\u0435 \u043a\u043e\u043d\u0444\u0438\u0433 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f) |\n| A2 | SN (\u043f\u043e\u0432\u0442\u043e\u0440 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0433\u043e \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u043e\u0433\u043e \u043f\u0435\u0440\u0438\u043e\u0434\u0430) | \u0432\u0441\u0435 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u044b | \u041f\u0435\u0440\u0438\u043e\u0434\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0431\u0435\u0439\u0437\u043b\u0430\u0439\u043d; \u0431\u0430\u0437\u0430 \u0434\u043b\u044f RRSE/RMAE |\n| A3 | Lin (\u043e\u0431\u044b\u0447\u043d\u0430\u044f \u043b\u0438\u043d\u0435\u0439\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c \u043d\u0430 \u0441\u044b\u0440\u043e\u043c \u0440\u044f\u0434\u0435) | \u0432\u0441\u0435 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u044b | \u0412\u043d\u0435\u0448\u043d\u0438\u0439 \u0431\u0435\u0439\u0437\u043b\u0430\u0439\u043d |\n| A4 | RC-Lin, `n_cycles` \u2208 {1,2,3,5} | ETTh1, ECL | \u0427\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043a \u0447\u0438\u0441\u043b\u0443 \u0446\u0438\u043a\u043b\u043e\u0432 |\n| A5 | RC-Lin, `r_cycle` \u2208 {\u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0439, \u00b11, \u0437\u0430\u0432\u0435\u0434\u043e\u043c\u043e \u043d\u0435\u0432\u0435\u0440\u043d\u044b\u0439, FFT-\u043e\u0446\u0435\u043d\u043a\u0430} | ETTh1 (+\u0441\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0430) | \u0412\u0430\u0436\u043d\u043e\u0441\u0442\u044c \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0433\u043e \u043f\u0435\u0440\u0438\u043e\u0434\u0430; \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0441\u0442\u044c |\n| A6 (\u043e\u043f\u0446.) | VC (\u043d\u0435-residual) | ETTh1, ECL | \u041e\u0442\u0434\u0435\u043b\u044f\u0435\u0442 \u0430\u0434\u0434\u0438\u0442\u0438\u0432\u043d\u0443\u044e \u0432\u0435\u0442\u0432\u044c \u043e\u0442 residual-\u0434\u0435\u043a\u043e\u043c\u043f\u043e\u0437\u0438\u0446\u0438\u0438 |\n| A7 (\u043e\u043f\u0446.) | RC-D-Linear / RC-NLinear | ETTh1, ECL | \u0417\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u044c \u0432\u044b\u0432\u043e\u0434\u0430 \u043e\u0442 backbone |\n\n\u041f\u0440\u0430\u0432\u0438\u043b\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f: \u0432\u043d\u0443\u0442\u0440\u0438 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430 \u0443 \u0412\u0421\u0415\u0425 \u043c\u043e\u0434\u0435\u043b\u0435\u0439 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 \u0441\u043f\u043b\u0438\u0442\u044b, \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f, \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0442\u043e\u0440, `lr`, `batch`, `epoch_\u0441ap`, `patience`, \u0441\u0438\u0434\u044b. \u041e\u0442\u043b\u0438\u0447\u0438\u0435 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u043d\u044b\u0439 \u0444\u0430\u043a\u0442\u043e\u0440.\n\n---\n\n## 6. \u041c\u0435\u0442\u0440\u0438\u043a\u0438 \u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0443\u0441\u043f\u0435\u0445\u0430\n\n### 6.1 \u041c\u0435\u0442\u0440\u0438\u043a\u0438\n- **MSE, MAE** \u2014 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0435, \u0430\u0433\u0440\u0435\u0433\u0430\u0446\u0438\u044f per-point \u043f\u043e \u0432\u0441\u0435\u043c \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u043c \u043e\u043a\u043d\u0430\u043c (\u043e\u0431\u0440\u0430\u0442\u043d\u043e\u0435 \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u043f\u0435\u0440\u0435\u0434 \u0440\u0430\u0441\u0447\u0451\u0442\u043e\u043c).\n- **RRSE, RMAE** \u2014 \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043a season-naive: `RRSE = RMSE_\u043c\u043e\u0434\u0435\u043b\u044c / RMSE_SN` (\u043c\u0430\u0441\u0448\u0442\u0430\u0431\u043d\u043e-\u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u0430\u044f \u0441\u0440\u0430\u0432\u043d\u0438\u043c\u043e\u0441\u0442\u044c \u043c\u0435\u0436\u0434\u0443 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430\u043c\u0438).\n- **\u041f\u043e-\u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442\u043d\u0430\u044f \u0440\u0430\u0437\u0431\u0438\u0432\u043a\u0430** \u043a\u0430\u0436\u0434\u043e\u0433\u043e `pred_len`.\n\n### 6.2 \u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0443\u0441\u043f\u0435\u0445\u0430 (\u043f\u0440\u0435-\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439, \u0444\u0430\u043b\u044c\u0441\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u044b\u0439)\n- **R1 (\u0441\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0430):** MSE(RC-Lin) < MSE(BO-Lin) \u0438 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u0430\u044f \u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0430 \u043a\u043e\u0440\u0440\u0435\u043b\u0438\u0440\u0443\u0435\u0442 \u0441 \u0438\u0441\u0442\u0438\u043d\u043d\u043e\u0439 (\u043f\u043e\u0441\u043b\u0435 \u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u044f \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0430/\u0444\u0430\u0437\u044b) \u0441 \u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442\u043e\u043c \u2265 0.9.\n- **R2 (\u043f\u0435\u0440\u0438\u043e\u0434\u0438\u043a\u0430):** \u043d\u0430 \u22653 \u0438\u0437 4 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432 MSE/MAE(RC-Lin) \u2264 MSE/MAE(BO-Lin); \u043f\u0440\u0438 \u044d\u0442\u043e\u043c \u043d\u0430 \u22652 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430\u0445 95% \u0431\u0443\u0442\u0441\u0442\u0440\u0430\u043f-\u0414\u0418 \u043f\u0430\u0440\u043d\u043e\u0439 \u0440\u0430\u0437\u043d\u0438\u0446\u044b (RC \u2212 BO) \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 0 \u0432 \u0441\u0442\u043e\u0440\u043e\u043d\u0443 \u0443\u0445\u0443\u0434\u0448\u0435\u043d\u0438\u044f (\u0442.\u0435. RC \u0437\u043d\u0430\u0447\u0438\u043c\u043e \u043d\u0435 \u0445\u0443\u0436\u0435, \u0436\u0435\u043b\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u043b\u0443\u0447\u0448\u0435).\n- **R3 (\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c):** \u043d\u0430 Exchange \u043f\u0430\u0440\u043d\u0430\u044f \u0440\u0430\u0437\u043d\u0438\u0446\u0430 (RC \u2212 BO) \u0438\u043c\u0435\u0435\u0442 95% \u0414\u0418, \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0449\u0438\u0439 0 (\u043d\u0435\u0442 \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0433\u043e \u0443\u0445\u0443\u0434\u0448\u0435\u043d\u0438\u044f), \u043b\u0438\u0431\u043e RC \u043b\u0443\u0447\u0448\u0435.\n- \u041e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0438\u0441\u0445\u043e\u0434\u044b \u043d\u0435 \u00ab\u043f\u0440\u043e\u0432\u0430\u043b \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430\u00bb: \u043c\u0430\u043b\u044b\u0439/\u043d\u0443\u043b\u0435\u0432\u043e\u0439/\u043d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442 \u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0432\u0435\u0442\u0432\u0438 \u2014 \u0441\u0430\u043c \u043f\u043e \u0441\u0435\u0431\u0435 \u0437\u043d\u0430\u0447\u0438\u043c\u044b\u0439 \u043d\u0430\u0443\u0447\u043d\u044b\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 (\u0434\u0438\u0437\u0430\u0439\u043d \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u0444\u0430\u043b\u044c\u0441\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044e R2/R3).\n\n---\n\n## 7. \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u044b\u0435 \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u044b\n1. **\u0411\u0435\u0437 \u0443\u0442\u0435\u0447\u0435\u043a:** \u0445\u0440\u043e\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0441\u043f\u043b\u0438\u0442 \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u043c\u0435\u0448\u0438\u0432\u0430\u043d\u0438\u044f; \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e train; val \u043d\u0435 \u0442\u0440\u043e\u0433\u0430\u0435\u0442 \u0442\u0435\u0441\u0442 (\u0440\u0430\u043d\u043d\u044f\u044f \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u0438 \u0432\u044b\u0431\u043e\u0440 \u0447\u0435\u043a\u043f\u043e\u0439\u043d\u0442\u0430 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e val).\n2. **\u0427\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u044c \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f:** \u0435\u0434\u0438\u043d\u044b\u0439 \u043a\u043e\u0434 \u0434\u0430\u0442\u0430-\u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d\u0430 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u043c\u043e\u0434\u0435\u043b\u0435\u0439; \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043a\u043e\u043d\u0444\u0438\u0433 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f; \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u043e\u0442\u043b\u0438\u0447\u0438\u0435 \u2014 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u043d\u044b\u0439 \u0444\u0430\u043a\u0442\u043e\u0440 (\u0435\u0441\u0442\u044c/\u043d\u0435\u0442 \u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0432\u0435\u0442\u0432\u044c; residual/vanilla).\n3. **\u0412\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c:** \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0441\u0438\u0434\u044b (\u0432\u0441\u0435 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u044b: numpy/torch/python), \u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u043e\u0431\u044a\u0435\u043a\u0442 \u0441\u043f\u043b\u0438\u0442\u0430 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u043c\u043e\u0434\u0435\u043b\u0435\u0439.\n4. **\u041d\u0430\u0431\u043b\u044e\u0434\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c:** \u043b\u043e\u0433\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 train/val loss \u0438 \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0445 \u043c\u0435\u0442\u0440\u0438\u043a \u0437\u0430 \u044d\u043f\u043e\u0445\u0443; \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435 \u043b\u0443\u0447\u0448\u0435\u0433\u043e \u0447\u0435\u043a\u043f\u043e\u0439\u043d\u0442\u0430 \u043f\u043e val MSE.\n5. **CPU-\u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u043e\u0441\u0442\u044c:** \u043c\u0430\u043b\u044b\u0435 \u043c\u043e\u0434\u0435\u043b\u0438 (Linear-\u043a\u043b\u0430\u0441\u0441, d_model \u2264 256), \u0443\u043d\u0438\u0432\u0430\u0440\u0438\u0430\u0442\u043d\u044b\u0435 \u0441\u0435\u0440\u0438\u0438; \u043d\u0430 224 CPU \u0432\u0441\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0438 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u043c\u0430\u0442\u0440\u0438\u0446\u044b \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u044b (\u043e\u0446\u0435\u043d\u043a\u0430: \u043c\u0438\u043d\u0443\u0442\u044b\u2013\u0447\u0430\u0441\u044b \u043d\u0430 5 \u0441\u0438\u0434\u043e\u0432/\u0434\u0430\u0442\u0430\u0441\u0435\u0442).\n\n---\n\n## 8. \u041f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430\n1. **\u0421\u0432\u043e\u0434\u043d\u0430\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430:** \u0434\u0430\u0442\u0430\u0441\u0435\u0442 \u00d7 \u043c\u043e\u0434\u0435\u043b\u044c \u00d7 \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442, mean\u00b1std \u043f\u043e 5 \u0441\u0438\u0434\u0430\u043c (MSE/MAE, RRSE/RMAE).\n2. **\u041f\u0430\u0440\u043d\u044b\u0439 \u0431\u0443\u0442\u0441\u0442\u0440\u0430\u043f:** \u043f\u043e \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u043c \u043e\u043a\u043d\u0430\u043c (\u0440\u0435\u0441\u0430\u043c\u043f\u043b\u0438\u043d\u0433 \u043e\u043a\u043e\u043d \u0441 \u0432\u043e\u0437\u0432\u0440\u0430\u0442\u043e\u043c, ~1000 \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0439) \u2014 95% \u0414\u0418 \u0434\u043b\u044f \u0440\u0430\u0437\u043d\u0438\u0446\u044b \u043c\u0435\u0442\u0440\u0438\u043a RC vs BO (\u0438 RC vs \u0431\u0435\u0439\u0437\u043b\u0430\u0439\u043d\u044b); \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0441\u0442\u044c = \u0414\u0418 \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 0.\n3. **\u041f\u043e-\u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442\u043d\u044b\u0435 \u043a\u0440\u0438\u0432\u044b\u0435** \u043e\u0448\u0438\u0431\u043e\u043a \u0434\u043b\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438, \u0433\u0434\u0435 \u0438\u043c\u0435\u043d\u043d\u043e \u0432\u044b\u0438\u0433\u0440\u044b\u0432\u0430\u0435\u0442 \u0446\u0438\u043a\u043b\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0432\u0435\u0442\u0432\u044c.\n4. **\u0410\u0431\u043b\u044f\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0430\u043d\u0430\u043b\u0438\u0437:** \u0442\u0430\u0431\u043b\u0438\u0446\u044b A4 (n_cycles), A5 (r_cycle), \u043e\u043f\u0446. A6/A7; \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0438 \u00ab\u0433\u0434\u0435 \u044d\u0444\u0444\u0435\u043a\u0442 \u0438\u0441\u0447\u0435\u0437\u0430\u0435\u0442\u00bb.\n5. **\u0410\u0443\u0434\u0438\u0442 \u0443\u0442\u0435\u0447\u0435\u043a:** \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u0447\u0442\u043e \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0438 \u0441\u043a\u0435\u0439\u043b\u0435\u0440\u0430 \u0432\u0437\u044f\u0442\u044b \u0442\u043e\u043b\u044c\u043a\u043e \u0438\u0437 train; \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u043f\u0435\u0440\u0435\u043c\u0435\u0448\u0438\u0432\u0430\u043d\u0438\u044f \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u043e\u043a\u043e\u043d; \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u0441\u043f\u043b\u0438\u0442\u043e\u0432 \u043c\u0435\u0436\u0434\u0443 \u043c\u043e\u0434\u0435\u043b\u044f\u043c\u0438 (\u0441\u043b\u0443\u0436\u0435\u0431\u043d\u044b\u0439 \u0442\u0435\u0441\u0442).\n\n---\n\n## 9. \u0427\u0435\u043a\u043b\u0438\u0441\u0442 \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438\n- [ ] \u0417\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u0432\u0435\u0440\u0441\u0438\u0438 Python \u0438 \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a (numpy, torch) \u0432 requirements/lock-\u0444\u0430\u0439\u043b\u0435.\n- [ ] \u0421\u0438\u0434\u044b \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u044b (5), \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u044b \u0434\u0430\u043d\u043d\u044b\u0445/\u0434\u0430\u043c\u043f\u0430.\n- [ ] JSON/YAML-\u043a\u043e\u043d\u0444\u0438\u0433 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u0441\u043e\u0445\u0440\u0430\u043d\u0451\u043d \u0441 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430\u043c\u0438.\n- [ ] CSV-\u043b\u043e\u0433\u0438 train/val/test \u043f\u043e \u044d\u043f\u043e\u0445\u0430\u043c \u0438 \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438.\n- [ ] \u0412\u0435\u0440\u0441\u0438\u0438 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432/\u0445\u0435\u0448\u0438, \u043a\u044d\u0448 \u043f\u0440\u0435\u0434\u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0438.\n- [ ] \u041a\u043e\u0434 + \u043a\u043e\u043d\u0444\u0438\u0433\u0438 \u0432 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438; \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0435 \u0437\u0430\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043e.\n- [ ] \u041e\u0433\u043e\u0432\u043e\u0440\u043a\u0430: \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 provisioned \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f \u0441 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u044f\u043c\u0438 \u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043e\u043c \u043a \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430\u043c (\u0432 \u0442\u0435\u043a\u0443\u0449\u0435\u0439 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0435 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442 \u2014 \u0441\u043c. \u00a710).\n\n---\n\n## 10. \u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u0438 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438 (\u044f\u0432\u043d\u044b\u0439 \u0441\u043f\u0438\u0441\u043e\u043a)\n\n**\u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (\u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u043a\u0430\u043a \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f \u0434\u0438\u0437\u0430\u0439\u043d\u0430):**\n- A1. \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0438\u0441\u0442\u0438\u043d\u044b \u043f\u043e \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0435 \u2014 \u0432\u043d\u0435\u0448\u043d\u0438\u0435 \u0441\u0442\u0430\u0442\u044c\u044f/\u0440\u0435\u043f\u043e CycleNet (ACAT-SCUT/CycleNet, ICLR 2025); \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b\u0445 \u0438\u0441\u0445\u043e\u0434\u043d\u0438\u043a\u043e\u0432 \u0432 workspace \u043d\u0435\u0442 (\u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043e). \u0422\u043e\u0447\u043d\u044b\u0435 \u0434\u0435\u0444\u043e\u043b\u0442\u044b (`r_cycle`, `n_cycles`, `lr`, scheduler) \u043f\u0435\u0440\u0435\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f \u0438\u0437 reference \u043a\u0430\u043a \u0437\u0430\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f.\n- A2. \u0418\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u043e\u0438\u0441\u0445\u043e\u0434\u0438\u0442 \u0432 \u0441\u0440\u0435\u0434\u0435 \u0441 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044b\u043c\u0438 numpy/torch \u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043e\u043c \u043a \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430\u043c; \u0432 \u0442\u0435\u043a\u0443\u0449\u0435\u0439 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0435 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0435\u0439 \u0438 \u0441\u0435\u0442\u0438 \u043d\u0435\u0442 \u2014 \u0434\u0438\u0437\u0430\u0439\u043d \u043d\u0435 \u043f\u0440\u0435\u0442\u0435\u043d\u0434\u0443\u0435\u0442 \u043d\u0430 \u0437\u0430\u043f\u0443\u0441\u043a \u0437\u0434\u0435\u0441\u044c.\n- A3. \u041c\u043e\u0434\u0435\u043b\u044c \u043c\u0430\u043b\u0430\u044f, CPU-only (224 CPU), GPU \u043d\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f.\n- A4. \u041e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442 \u2014 residual CycleNet (\u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439); vanilla \u2014 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u0430\u044f \u0430\u0431\u043b\u044f\u0446\u0438\u044f.\n- A5. \u0410\u0433\u0440\u0435\u0433\u0430\u0446\u0438\u044f \u043c\u0435\u0442\u0440\u0438\u043a \u2014 per-point (\u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442 LTSF).\n- A6. \u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0443\u0441\u043f\u0435\u0445\u0430 \u2014 \u043f\u0440\u0435-\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 (\u0441\u043c. \u00a76.2), \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0438\u0441\u0445\u043e\u0434.\n\n**\u041d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438 (\u0440\u0435\u0448\u0435\u043d\u0438\u044f \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430\u0442\u043e\u0440\u0430, \u0441 \u043e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435\u043c):**\n- U1. \u0414\u0435\u0444\u043e\u043b\u0442\u043d\u044b\u0435 \u0433\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b reference-\u0440\u0435\u043f\u043e \u043d\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u044b \u0431\u0435\u0437 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u043a \u0441\u0435\u0442\u0438 \u2014 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0438\u0437 \u0441\u0442\u0430\u0442\u044c\u0438 \u0438 \u044f\u0432\u043d\u043e \u043f\u043e\u043c\u0435\u0447\u0430\u044e\u0442\u0441\u044f \u0432 \u043a\u043e\u043d\u0444\u0438\u0433\u0435; \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u2014 \u044d\u043c\u043f\u0438\u0440\u0438\u0447\u0435\u0441\u043a\u0430\u044f (A4/A5).\n- U2. \u0422\u043e\u0447\u043d\u044b\u0439 \u043f\u0435\u0440\u0438\u043e\u0434 `r_cycle` \u043d\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430\u0445 (24/96/144/168) \u2014 \u0437\u0430\u0434\u0430\u0451\u0442\u0441\u044f \u0434\u043e\u043c\u0435\u043d\u043d\u043e, \u0437\u0430\u0442\u0435\u043c \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442\u0441\u044f FFT/\u0430\u0432\u0442\u043e\u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u0435\u0439 \u043d\u0430 train (\u043d\u0435 \u043d\u0430 \u0442\u0435\u0441\u0442\u0435).\n- U3. \u0411\u044e\u0434\u0436\u0435\u0442 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0439 (\u0447\u0438\u0441\u043b\u043e \u0441\u0438\u0434\u043e\u0432 = 5, \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442\u043e\u0432 \u0434\u043b\u044f Solar/Exchange) \u2014 \u043a\u043e\u043c\u043f\u0440\u043e\u043c\u0438\u0441\u0441 \u043c\u0435\u0436\u0434\u0443 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043d\u0430\u0434\u0451\u0436\u043d\u043e\u0441\u0442\u044c\u044e \u0438 CPU-\u0432\u0440\u0435\u043c\u0435\u043d\u0435\u043c.\n- U4. \u0423\u043d\u0438\u0432\u0430\u0440\u0438\u0430\u0442\u043d\u044b\u0439 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u0432\u044b\u0431\u0440\u0430\u043d \u0431\u0430\u0437\u043e\u0432\u044b\u043c (\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u044c \u0438 \u043f\u0440\u043e\u0441\u0442\u043e\u0442\u0430 fair comparison); \u043c\u0443\u043b\u044c\u0442\u0438\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u043d\u044b\u0439 \u2014 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0435 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435, \u043d\u0435 \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0443\u0441\u043f\u0435\u0445\u0430.\n- U5. \u041f\u043e\u0440\u043e\u0433 R2 (\u00ab\u22653 \u0438\u0437 4 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432\u00bb, \u00ab\u22652 \u0441\u043e \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0439 \u0440\u0430\u0437\u043d\u0438\u0446\u0435\u0439\u00bb) \u2014 \u044d\u043a\u0441\u043f\u0435\u0440\u0442\u043d\u043e\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u0434\u043b\u044f \u0431\u0430\u043b\u0430\u043d\u0441\u0430 \u043c\u0435\u0436\u0434\u0443 \u0436\u0451\u0441\u0442\u043a\u043e\u0441\u0442\u044c\u044e \u0438 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c\u044e.\n\n**\u041f\u0440\u044f\u043c\u043e\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435:** \u044d\u0442\u043e \u0434\u0438\u0437\u0430\u0439\u043d-\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442; \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0439 \u043e \u0442\u043e\u043c, \u0447\u0442\u043e \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u043b\u0441\u044f, \u043d\u0435\u0442.", "evidence": "\u041f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043e \u0432 /workspace: \u0442\u043e\u043b\u044c\u043a\u043e task.json (\u0432\u043e\u043f\u0440\u043e\u0441 + \u00abDesign-only task; repositories and compute are not required\u00bb; track.md \u043d\u0430 \u0434\u0438\u0441\u043a\u0435 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u2014 find / -name track.md \u043f\u0443\u0441\u0442). \u0421\u0440\u0435\u0434\u0430: Python 3.14.4, 224 CPU, ~2 TB RAM, GPU disabled, network disabled; importlib-\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430: numpy/pandas/sklearn/scipy/torch/statsmodels/matplotlib/tqdm/einops \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442; pip download numpy \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442\u0441\u044f \u043e\u0448\u0438\u0431\u043a\u043e\u0439 (\u043d\u0435\u0442 \u0441\u0435\u0442\u0438). \u0417\u043d\u0430\u0447\u0438\u0442, \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b\u0445 \u0432\u0435\u0440\u0441\u0438\u0439 CycleNet, \u043a\u043e\u043d\u0444\u0438\u0433\u043e\u0432, \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a \u0438 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432 \u043d\u0435\u0442; \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u043e\u043f\u043e\u0440\u043d\u044b\u0439 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u2014 \u0432\u043d\u0435\u0448\u043d\u044f\u044f \u0441\u0442\u0430\u0442\u044c\u044f/\u0440\u0435\u043f\u043e CycleNet (ICLR 2025). \u041d\u0430 \u043e\u0441\u043d\u043e\u0432\u0435 \u044d\u0442\u043e\u0433\u043e \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d \u043f\u043e\u043b\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d: \u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b (R1\u2013R3), \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f residual CycleNet \u0441 \u0444\u043e\u0440\u043c\u0443\u043b\u0430\u043c\u0438 (\u0441\u043b\u043e\u0432\u0430\u0440\u044c W \u2208 R^{n\u00d7r}, \u043e\u0441\u0442\u0430\u0442\u043e\u043a z = x \u2212 c, \u043f\u0440\u043e\u0433\u043d\u043e\u0437 = \u043e\u0441\u0442\u0430\u0442\u043e\u043a + \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0435\u043d\u043d\u044b\u0439 \u0446\u0438\u043a\u043b), \u043f\u0440\u043e\u0442\u043e\u043a\